# ==============================================================================
# 0.1 PROYECCIÓN ALBERS (EEUU continental) — MISMOS parámetros y escala usados
# para generar los polígonos de estado embebidos en US_STATES_GEO_JSON. Cualquier
# punto adicional (ej. centroide de ZIP) debe proyectarse con esta MISMA función
# para caer alineado sobre esas fronteras ya "horneadas" en el SVG.
# ==============================================================================
_ALBERS_PHI1 = math.radians(29.5)
_ALBERS_PHI2 = math.radians(45.5)
_ALBERS_LAMBDA0 = math.radians(-96)
_ALBERS_N = (math.sin(_ALBERS_PHI1) + math.sin(_ALBERS_PHI2)) / 2
_ALBERS_C = math.cos(_ALBERS_PHI1) ** 2 + 2 * _ALBERS_N * math.sin(_ALBERS_PHI1)
_ALBERS_SCALE = 1250.62768752673
_ALBERS_OFFSET_X = 489.81133230068883
_ALBERS_OFFSET_Y = -1303.8699399995664


def project_albers_conus(lat: float, lon: float) -> tuple:
    phi = math.radians(lat)
    lam = math.radians(lon)
    theta = _ALBERS_N * (lam - _ALBERS_LAMBDA0)
    rho = math.sqrt(_ALBERS_C - 2 * _ALBERS_N * math.sin(phi)) / _ALBERS_N
    x = rho * math.sin(theta)
    y = rho * math.cos(theta)
    return x * _ALBERS_SCALE + _ALBERS_OFFSET_X, y * _ALBERS_SCALE + _ALBERS_OFFSET_Y


# ==============================================================================
# 0.2 LOOKUP AUTOMÁTICO DE LAT/LON POR ZIP (ZCTA Gazetteer, US Census Bureau)
# ==============================================================================
ZCTA_GAZETTEER_URL = "https://www2.census.gov/geo/docs/maps-data/data/gazetteer/2023_Gazetteer/2023_Gaz_zcta_national.zip"
ZCTA_CACHE_PATH = Path(__file__).resolve().parent / "zcta_centroids.csv"


def load_zip_centroids(zips) -> dict:
    """
    Resuelve lat/lon para una lista de ZIP codes contra el ZCTA Gazetteer del
    Census Bureau (gratis, sin API key, ~33k ZIPs, cubre EEUU completo). Cachea
    un CSV reducido (Scripts/zcta_centroids.csv) la primera vez que se ejecuta,
    así que ZIPs nuevos en meses futuros se resuelven automáticamente sin tocar
    código — solo hay que volver a correr el script.

    Si zcta_centroids.csv ya existe (por ejemplo, versionado en el repo), no se
    vuelve a descargar nada — funciona sin internet.
    """
    zips = sorted({str(z).strip().zfill(5)[:5] for z in zips if str(z).strip()})
    if not zips:
        return {}

    if not ZCTA_CACHE_PATH.exists():
        with urllib.request.urlopen(ZCTA_GAZETTEER_URL, timeout=30) as resp:
            raw = resp.read()
        with zipfile.ZipFile(io.BytesIO(raw)) as zf:
            txt_name = next(n for n in zf.namelist() if n.endswith(".txt"))
            with zf.open(txt_name) as f:
                gaz = pd.read_csv(f, sep="\t")
        gaz.columns = [c.strip() for c in gaz.columns]
        gaz["GEOID"] = gaz["GEOID"].astype(str).str.zfill(5)
        gaz[["GEOID", "INTPTLAT", "INTPTLONG"]].to_csv(ZCTA_CACHE_PATH, index=False)

    gaz = pd.read_csv(ZCTA_CACHE_PATH, dtype={"GEOID": str}).set_index("GEOID")
    out = {}
    for z in zips:
        if z in gaz.index:
            row = gaz.loc[z]
            out[z] = (float(row["INTPTLAT"]), float(row["INTPTLONG"]))
    return out

