# ==============================================================================
# 2. CLASIFICACIÓN — misma lógica en cascada de Sullivan_data_guide.md (§2/§3.2)
# ==============================================================================
def classify_orders(df: pd.DataFrame) -> pd.DataFrame:
    """
    Aplica la Matriz de Prioridades (1-9) de la guía sobre un DataFrame a nivel
    ítem de Apr_OrderSales. Devuelve el mismo df + columna 'Final Category'.

    Nota: el export real de Apr_OrderSales NO trae columna de 'Order Tag'
    (ver hallazgo documentado en sullivan_c7_simulator.py), así que Event /
    Corporate / Friends & Family solo se activan si existe una columna
    'Order Tag' o 'Order Tags' en el archivo de entrada. Si no existe, todo
    Inbound cae en Telesales — que es exactamente lo observado en abril real.
    """
    d = df.copy()
    channel = d.get("Channel", pd.Series("", index=d.index)).fillna("").str.strip().str.lower()
    vendor = d.get("External Order Vendor", pd.Series("", index=d.index)).fillna("").str.strip().str.lower()
    club_title = d.get("Club Title", pd.Series("", index=d.index)).fillna("").astype(str).str.strip()
    club_package = d.get("Club Package", pd.Series("", index=d.index)).fillna("").astype(str)

    tag_col = None
    for candidate in ("Order Tag", "Order Tags"):
        if candidate in d.columns:
            tag_col = candidate
            break
    tags = d[tag_col].fillna("").astype(str) if tag_col else pd.Series("", index=d.index)

    cond_event = (channel == "inbound") & tags.str.contains("Event", case=False)
    cond_corp = (channel == "inbound") & tags.str.contains("Corporate", case=False)
    cond_ff = (channel == "inbound") & tags.str.contains("Friends & Family|Friends and Family", case=False)
    cond_tele = (channel == "inbound")

    cond_tock = (channel == "web") & (vendor == "tock")
    cond_web = (channel == "web")

    cond_pos = (channel == "pos")

    is_club = channel == "club"
    # Admin/POS marcado como Club: canal Club pero sin Club Title/Package coherente,
    # o canal distinto de Club con Club Title poblado (anomalía inversa).
    cond_club_review = is_club & (club_title == "") & (club_package == "")
    cond_estate = is_club & ~cond_club_review & (club_title.str.contains("Estate", case=False) | club_package.str.contains("Estate", case=False))
    cond_founders = is_club & ~cond_club_review & ~cond_estate

    conditions = [cond_event, cond_corp, cond_ff, cond_tele, cond_tock, cond_web,
                  cond_pos, cond_estate, cond_founders, cond_club_review]
    choices = ["Event", "Corporate", "Friends & Family", "Telesales", "Tock",
               "Web / Ecommerce", "Tasting Room", "Estate Club", "Founder's Club",
               "Club - Review (Admin/POS)"]
    d["Final Category"] = np.select(conditions, choices, default="Unassigned")

    def package_group(pkg: str) -> str:
        p = pkg.lower()
        if "estate" in p:
            # Ojo: el nombre del paquete incluye el año (ej. "April 2026 Estate 4"),
            # así que NO basta con buscar "6" en todo el string (2026 tiene un 6).
            # Se busca el dígito que sigue explícitamente a la palabra "estate".
            m = re.search(r"estate\s*(\d+)", p)
            return "Estate 6 Bottle" if (m and m.group(1) == "6") else "Estate 4 Bottle"
        if "3 bottle" in p:
            return "Founder's 3 Bottle"
        if "half" in p:
            return "Founder's Half Case"
        if "single" in p:
            return "Founder's Single Case"
        if "double" in p:
            return "Founder's Double Case"
        return ""

    d["Club Package Group"] = club_package.map(package_group)
    return d


# ==============================================================================
# 3. AGREGACIONES PARA LAS 2 VISTAS DEL DASHBOARD
# ==============================================================================
def money_col(d):
    for c in ("Product SubTotal", "SubTotal", "Total"):
        if c in d.columns:
            return c
    raise KeyError("No se encontró columna de monto (Product SubTotal / SubTotal / Total).")


def build_vista_a(d: pd.DataFrame) -> dict:
    amt_col = money_col(d)
    order_col = "Order Number" if "Order Number" in d.columns else "Id"
    g = d.groupby("Final Category").agg(
        orders=(order_col, "nunique"),
        subtotal=(amt_col, "sum"),
    ).reindex(CATEGORY_ORDER).fillna(0).reset_index()
    total_dtc = g["subtotal"].sum()
    g["pct"] = np.where(total_dtc > 0, (g["subtotal"] / total_dtc * 100).round(2), 0)
    # Ordenar categorías de mayor a menor por venta neta (SubTotal)
    g = g.sort_values(by="subtotal", ascending=False).reset_index(drop=True)
    return {
        "categories": g["Final Category"].tolist(),
        "orders": g["orders"].astype(int).tolist(),
        "subtotal": g["subtotal"].round(2).tolist(),
        "pct": g["pct"].tolist(),
        "colors": [CATEGORY_COLORS.get(c, "#656565") for c in g["Final Category"]],
        "total_dtc": round(float(total_dtc), 2),
    }


def build_vista_b(d: pd.DataFrame) -> dict:
    amt_col = money_col(d)
    order_col = "Order Number" if "Order Number" in d.columns else "Id"
    club_mask = d["Final Category"].isin(["Estate Club", "Founder's Club"])
    club_df = d[club_mask]

    pkg_order = list(CLUB_PACKAGE_COLORS.keys())
    g = club_df.groupby("Club Package Group").agg(
        orders=(order_col, "nunique"),
        subtotal=(amt_col, "sum"),
    ).reindex(pkg_order).fillna(0).reset_index()
    g["aov"] = np.where(g["orders"] > 0, (g["subtotal"] / g["orders"]).round(2), 0)
    # Ordenar paquetes de mayor a menor por venta neta (SubTotal)
    g = g.sort_values(by="subtotal", ascending=False).reset_index(drop=True)

    estate_total = float(club_df[club_df["Final Category"] == "Estate Club"][amt_col].sum())
    founders_total = float(club_df[club_df["Final Category"] == "Founder's Club"][amt_col].sum())

    review = d[d["Final Category"] == "Club - Review (Admin/POS)"]
    review_cols = [c for c in ("Order Number", "Order Submitted Date", "Channel", amt_col) if c in review.columns]
    review_records = review[review_cols].rename(columns={amt_col: "SubTotal"})
    if "Order Submitted Date" in review_records.columns:
        review_records["Order Submitted Date"] = review_records["Order Submitted Date"].astype(str)

    return {
        "packages": g["Club Package Group"].tolist(),
        "orders": g["orders"].astype(int).tolist(),
        "subtotal": g["subtotal"].round(2).tolist(),
        "aov": g["aov"].tolist(),
        "colors": [CLUB_PACKAGE_COLORS.get(p, "#8C2F2F") for p in g["Club Package Group"]],
        "estate_total": round(estate_total, 2),
        "founders_total": round(founders_total, 2),
        "review_cases": review_records.to_dict(orient="records"),
    }


US_STATE_CODES = {
    "AL","AK","AZ","AR","CA","CO","CT","DE","FL","GA","HI","ID","IL","IN","IA","KS","KY",
    "LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ","NM","NY","NC","ND",
    "OH","OK","OR","PA","RI","SC","SD","TN","TX","UT","VT","VA","WA","WV","WI","WY","DC",
}


def build_geo(d: pd.DataFrame) -> dict:
    """
    Distribución geográfica de los ENVÍOS DE CLUB (Estate + Founder's).
    Se ancla a Club porque ahí vive la logística física de envío (85% de la
    venta), a diferencia de Tasting Room/Telesales donde el estado de
    facturación no implica un envío real. Usa 'Ship To ...' y cae a
    'Bill To ...' si el envío está vacío (ej. pickup en bodega).
    """
    amt_col = money_col(d)
    order_col = "Order Number" if "Order Number" in d.columns else "Id"
    club_df = d[d["Final Category"].isin(["Estate Club", "Founder's Club"])].copy()

    def pick(col_ship, col_bill):
        ship = club_df[col_ship] if col_ship in club_df.columns else pd.Series("", index=club_df.index)
        bill = club_df[col_bill] if col_bill in club_df.columns else pd.Series("", index=club_df.index)
        return ship.fillna("").astype(str).str.strip().where(lambda s: s != "", bill.fillna("").astype(str).str.strip())

    club_df["_state"] = pick("Ship To State Code", "Bill To State Code").str.upper()
    club_df["_zip"] = pick("Ship To Zip Code", "Bill To Zip Code")
    club_df["_state"] = club_df["_state"].where(club_df["_state"].isin(US_STATE_CODES), "")

    by_state = club_df[club_df["_state"] != ""].groupby("_state").agg(
        orders=(order_col, "nunique"), subtotal=(amt_col, "sum"),
    ).reset_index().sort_values("subtotal", ascending=False)

    by_zip = club_df[club_df["_zip"] != ""].groupby("_zip").agg(
        orders=(order_col, "nunique"), subtotal=(amt_col, "sum"),
    ).reset_index().sort_values("subtotal", ascending=False).head(15)

    unresolved = int((club_df["_state"] == "").sum())

    zip_list = by_zip["_zip"].tolist()
    centroids = load_zip_centroids(zip_list)
    zip_points = []
    unresolved_zips = []
    for z, orders, sub in zip(zip_list, by_zip["orders"].astype(int).tolist(), by_zip["subtotal"].round(2).tolist()):
        if z in centroids:
            lat, lon = centroids[z]
            x, y = project_albers_conus(lat, lon)
            zip_points.append({"zip": z, "x": round(x, 1), "y": round(y, 1), "orders": orders, "subtotal": sub})
        else:
            unresolved_zips.append(z)

    return {
        "states": by_state["_state"].tolist(),
        "state_orders": by_state["orders"].astype(int).tolist(),
        "state_subtotal": by_state["subtotal"].round(2).tolist(),
        "zips": zip_list,
        "zip_orders": by_zip["orders"].astype(int).tolist(),
        "zip_subtotal": by_zip["subtotal"].round(2).tolist(),
        "zip_points": zip_points,
        "unresolved_zips": unresolved_zips,
        "unresolved_rows": unresolved,
    }


def build_reconciliation(vista_a: dict, financial_report_path: str | None) -> dict:
    total_dtc = vista_a["total_dtc"]
    net_sales_financial = None
    if financial_report_path:
        try:
            fin = load_data_file(financial_report_path)
            for c in ("SubTotal", "Sub Total"):
                if c in fin.columns:
                    net_sales_financial = round(float(fin[c].sum()), 2)
                    break
        except Exception:
            net_sales_financial = None

    ok = None
    if net_sales_financial is not None:
        ok = bool(np.isclose(total_dtc, net_sales_financial, atol=1.0))

    return {
        "total_dtc": total_dtc,
        "net_sales_financial": net_sales_financial,
        "match": ok,
    }


def render_svg_map_html(geo: dict) -> str:
    """Genera el SVG del mapa coroplético de EE.UU. pre-renderizado estáticamente con escala Cabernet."""
    geo_dict = json.loads(US_STATES_GEO_JSON)
    paths = geo_dict.get("paths", {})
    centroids = geo_dict.get("centroids", {})

    state_sub = dict(zip(geo.get("states", []), geo.get("state_subtotal", [])))
    state_ord = dict(zip(geo.get("states", []), geo.get("state_orders", [])))
    max_sub = max(geo.get("state_subtotal", [1.0]) + [1.0])

    svg_parts = [
        '<svg id="chart-geo-states" viewBox="0 0 960 600" '
        'style="width:100%;max-width:960px;height:auto;aspect-ratio:960/600;display:block;margin:0 auto;">'
    ]

    for code, path_d in paths.items():
        sub = state_sub.get(code, 0.0)
        ords = state_ord.get(code, 0)
        if sub > 0:
            # Escala no lineal (potencia 0.42) para que estados con ventas intermedias se diferencien claramente
            t = min(1.0, max(0.0, (sub / max_sub) ** 0.42))
            c0 = (235, 214, 206)  # Tint suave Cabernet
            c1 = (84, 18, 26)     # Cabernet profundo Sullivan
            r = int(c0[0] + (c1[0] - c0[0]) * t)
            g = int(c0[1] + (c1[1] - c0[1]) * t)
            b = int(c0[2] + (c1[2] - c0[2]) * t)
            fill = f"rgb({r},{g},{b})"
            stroke = "#003057"
            stroke_width = "1.2"
        else:
            # Estados sin ventas: gris neutro elegante claramente distinguible
            fill = "#EFECE6"
            stroke = "#C8C2B8"
            stroke_width = "0.8"

        svg_parts.append(
            f'<path class="state-path" data-code="{code}" data-orders="{ords}" data-subtotal="{sub:.2f}" '
            f'd="{path_d}" fill="{fill}" stroke="{stroke}" stroke-width="{stroke_width}" stroke-linejoin="round">'
            f'<title>{code}: {ords} órdenes, ${sub:,.0f}</title></path>'
        )

    for code, (cx, cy) in centroids.items():
        sub = state_sub.get(code, 0.0)
        if sub > 0:
            t = min(1.0, (sub / max_sub) ** 0.42)
            lbl_color = "#FFFFFF" if t > 0.6 else "#451B0F"
            svg_parts.append(
                f'<text x="{cx}" y="{cy}" text-anchor="middle" font-size="9.5" font-weight="700" fill="{lbl_color}" pointer-events="none">{code}</text>'
            )

    zip_points = geo.get("zip_points", [])
    max_zip_ords = max([p.get("orders", 1) for p in zip_points] + [1])
    for p in zip_points:
        z = p.get("zip", "")
        ords = p.get("orders", 0)
        sub = p.get("subtotal", 0.0)
        x = p.get("x", 0)
        y = p.get("y", 0)
        r = round(4.0 + (ords / max_zip_ords) * 11.0, 1)
        svg_parts.append(
            f'<circle class="zip-circle" data-zip="{z}" data-orders="{ords}" data-subtotal="{sub:.2f}" '
            f'cx="{x}" cy="{y}" r="{r}" fill="#C79F6C" stroke="#003057" stroke-width="1.5" opacity="0.94">'
            f'<title>Código Postal (ZIP) {z}: {ords} órdenes, ${sub:,.0f}</title></circle>'
        )

    svg_parts.append('</svg>')
    return "\n".join(svg_parts)


# ==============================================================================
# 4. ASSETS DE MARCA (fuente + logo embebidos como base64 -> archivo standalone)
# ==============================================================================
def font_face_css() -> str:
    faces = []
    mapping = [
        ("EBGaramond-Regular.ttf", 400, "normal"),
        ("EBGaramond-Medium.ttf", 500, "normal"),
        ("EBGaramond-SemiBold.ttf", 600, "normal"),
        ("EBGaramond-Bold.ttf", 700, "normal"),
        ("EBGaramond-Italic.ttf", 400, "italic"),
    ]
    for fname, weight, style in mapping:
        fpath = FONT_DIR / fname
        if fpath.exists():
            b64 = base64.b64encode(fpath.read_bytes()).decode("ascii")
            faces.append(f"""
@font-face {{
  font-family: 'EB Garamond';
  src: url(data:font/ttf;base64,{b64}) format('truetype');
  font-weight: {weight};
  font-style: {style};
}}""")
    return "\n".join(faces)


def logo_white_data_uri() -> str:
    if LOGO_WHITE_SVG.exists() and LOGO_WHITE_SVG.stat().st_size > 100:
        b64 = base64.b64encode(LOGO_WHITE_SVG.read_bytes()).decode("ascii")
        return f"data:image/svg+xml;base64,{b64}"
    return ""


