def load_data_file(path_str: str | Path) -> pd.DataFrame:
    """Carga un archivo de datos en formato Excel (.xlsx/.xls) o CSV (.csv)."""
    p = Path(path_str)
    if not p.exists():
        raise FileNotFoundError(f"No se encontró el archivo de datos: {p}")
    if p.suffix.lower() == ".csv":
        try:
            return pd.read_csv(p, encoding="utf-8")
        except UnicodeDecodeError:
            return pd.read_csv(p, encoding="latin1")
    return pd.read_excel(p)


CHART_JS_PATH = PROJECT_ROOT / "Scripts" / "chart.umd.min.js"


def get_chart_js_inline() -> str:
    """Retorna el código de Chart.js local para embeber de forma 100% standalone."""
    if CHART_JS_PATH.exists():
        try:
            return CHART_JS_PATH.read_text(encoding="utf-8")
        except Exception:
            return ""
    return ""


# ==============================================================================
# 6. MAIN
# ==============================================================================
def generate(order_sales_path: str, financial_report_path: str | None,
             output_path: str, title: str, period_label: str):
    df = load_data_file(order_sales_path)
    df = classify_orders(df)

    vista_a = build_vista_a(df)
    vista_b = build_vista_b(df)
    vista_b["geo"] = build_geo(df)
    reconciliation = build_reconciliation(vista_a, financial_report_path)

    report_data = {
        "vista_a": vista_a,
        "vista_b": vista_b,
        "reconciliation": reconciliation,
        "meta": {"period_label": period_label, "generated_at": datetime.now().isoformat()},
    }

    html = HTML_TEMPLATE.format(
        title=title,
        period_label=period_label,
        font_faces=font_face_css(),
        chart_js_inline=get_chart_js_inline(),
        svg_map_html=render_svg_map_html(vista_b["geo"]),
        logo_html=f'<img src="{logo_white_data_uri()}" alt="Sullivan Rutherford Estate" />' if logo_white_data_uri() else "",
        report_data_json=json.dumps(report_data),
        us_states_geo_json=US_STATES_GEO_JSON,
        generated_at=datetime.now().strftime("%b %d, %Y %H:%M"),
        data_note="simulada" if "sim" in Path(order_sales_path).stem.lower() else "real/exportada",
        **TOKENS,
    )

    out = Path(output_path)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(html, encoding="utf-8")
    print(f"Dashboard generado: {out}")
    print(f"  Total DTC: ${vista_a['total_dtc']:,.2f}")
    print(f"  Reconciliación vs Financial Report: {reconciliation['match']}")


def main():
    ap = argparse.ArgumentParser(description="Genera el dashboard base Vista A + Vista B de Sullivan.")
    ap.add_argument("--order-sales", required=True, help="Ruta a Apr_OrderSales.xlsx (o equivalente simulado).")
    ap.add_argument("--financial-report", default=None, help="Ruta a Apr_FinancialReport.xlsx (opcional).")
    ap.add_argument("--output", default="Data_for_demo/sullivan_dashboard.html")
    ap.add_argument("--title", default="Sullivan Rutherford Estate — DTC Sales Dashboard")
    ap.add_argument("--period-label", default="April 2026")
    args = ap.parse_args()
    generate(args.order_sales, args.financial_report, args.output, args.title, args.period_label)


if __name__ == "__main__":
    main()
